parameters.jsCode:
/*
  Eingangspruefung
  ----------------
  Prueft die Anfrage, bevor sie in den KI-Pfad geht, und setzt das Feld
  pruefung auf einen von vier Werten: sensibel, produktionskritisch,
  unvollstaendig oder ok.

  Die Reihenfolge der Pruefungen ist Fachlogik und darf nicht vertauscht
  werden. Vertraulichkeit geht vor Eilbeduerftigkeit, und ein Eilfall darf
  nicht wegen einer fehlenden Angabe in der Nachforderungsschleife haengen.
*/

// Begriffe, die auf einen personalbezogenen oder vertraulichen Vorgang
// hindeuten. Bewusst grosszuegig gewaehlt: ein Fehlalarm kostet nur eine
// manuelle Sichtung, ein uebersehener Fall verletzt eine Vorgabe.
const SENSIBEL = [
  'abmahnung', 'kuendigung', 'kündigung', 'personalakte', 'personalgespraech',
  'personalgespräch', 'gehalt', 'lohnabrechnung', 'entgelt', 'abfindung',
  'aufhebungsvertrag', 'krankmeldung', 'krankschreibung', 'arbeitsunfaehig',
  'arbeitsunfähig', 'attest', 'diagnose', 'schwerbehinderung',
  'wiedereingliederung', 'mutterschutz', 'elternzeit', 'betriebsrat',
  'personalrat', 'mitbestimmung', 'hinweisgeber', 'whistleblow', 'meldestelle',
  'bewerbung', 'bewerber', 'zeugnis', 'mobbing', 'belaestigung', 'belästigung'
];

// Beide Freitextfelder zusammen durchsuchen, alles kleingeschrieben,
// damit die Schreibweise keine Rolle spielt.
const suchfeld = ($json.kurzbeschreibung + ' ' + $json.text).toLowerCase();

// Alle Treffer sammeln, damit im Pruefgrund steht, welches Wort ausgeloest hat.
// Das braucht die Person, die den Fall danach manuell sichtet.
const treffer = SENSIBEL.filter(wort => suchfeld.includes(wort));

let pruefung;
let pruefgrund;

if (treffer.length > 0) {
  // 1. Vertraulichkeit zuerst. Weder Notion noch das Sprachmodell sehen den Fall.
  pruefung = 'sensibel';
  pruefgrund = 'Begriff erkannt: ' + treffer.join(', ');

} else if ($json.produktion === true) {
  // 2. Eilfall. Umgeht den KI-Pfad, weil eine Fehleinstufung hier
  //    den Produktionsstillstand verlaengert.
  pruefung = 'produktionskritisch';
  pruefgrund = 'Produktion betroffen';

} else if (!$json.geraet || !$json.standort) {
  // 3. Erst jetzt stoert eine Luecke. Der Pruefgrund nennt die fehlenden
  //    Felder einzeln, damit die Nachforderung konkret werden kann.
  const fehlt = [];
  if (!$json.geraet)   fehlt.push('Geraetename');
  if (!$json.standort) fehlt.push('Standort');
  pruefung = 'unvollstaendig';
  pruefgrund = 'Fehlende Angaben: ' + fehlt.join(', ');

} else {
  // 4. Alles in Ordnung, der Vorgang darf in die Wissenssuche.
  pruefung = 'ok';
  pruefgrund = '';
}

// Die urspruenglichen Felder bleiben erhalten, die zwei neuen kommen dazu.
return { json: { ...$json, pruefung, pruefgrund } };

/*
  Treffer bewerten
  ----------------
  Vergleicht die Stichworte der gefundenen Artikel mit dem Suchtext der
  Anfrage und waehlt den besten Treffer aus.

  Ab hier fuehren wir Anfrage und Suchergebnis wieder zusammen. Die Anfrage
  holen wir uns direkt vom Node "Suchtext bilden", weil der Notion-Node sie
  aus dem Datenstrom verdraengt hat.
*/

const anfrage = $('Suchtext bilden').first().json;

// Dieselbe Normalisierung wie im Node davor. Beide Seiten muessen gleich
// behandelt werden, sonst findet "zuruecksetzen" nie "zurücksetzen".
function normalisieren(s) {
  return (s || '')
    .toLowerCase()
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss');
}

/*
  Ab wie vielen Punkten gilt ein Artikel als geeigneter Treffer.
  Das ist die zentrale Stellschraube des gesamten Workflows und zugleich
  die Groesse, die ueber die Kennzahl Trefferquote entscheidet.
  Zu niedrig bedeutet viele unpassende Vorschlaege, zu hoch bedeutet,
  dass der Assistent fast nie etwas findet.
*/
const SCHWELLWERT = 1;

/*
  Leere Items herausfiltern. Bei null Treffern liefert der Notion-Node wegen
  "Always Output Data" ein leeres Item, das hier nicht mitgezaehlt werden darf.
*/
const kandidaten = $input.all()
  .map(item => item.json)
  .filter(artikel => artikel && artikel.property_kennung);

let beste = null;

for (const artikel of kandidaten) {

  // Ein Stichwort zaehlt, wenn es irgendwo im Suchtext vorkommt, auch als
  // Teil eines laengeren Wortes. Dadurch findet "drucker" auch
  // "Etikettendrucker".
  const stichworte = (artikel.property_stichworte || []).map(normalisieren);
  const getroffen = stichworte.filter(s => s && anfrage.suchtext.includes(s));

  // Woerter aus dem Titel zaehlen zusaetzlich, aber nur halb. Sie sind ein
  // schwaecheres Signal als ein bewusst vergebenes Stichwort.
  const titelwoerter = normalisieren(artikel['property_titel'])
    .split(/[^a-z0-9]+/)
    .filter(wort => wort.length >= 5);
  const titeltreffer = titelwoerter.filter(wort => anfrage.suchtext.includes(wort));

  const score = getroffen.length + titeltreffer.length * 0.5;

  if (!beste || score > beste.score) {
    beste = {
      score: score,
      getroffen: getroffen,
      kennung: artikel.property_kennung,
      titel: artikel['property_titel'],
      pruefdatum: artikel['property_prüfdatum'] ? artikel['property_prüfdatum'].start : '',
      loesung: artikel['property_lösungstext'] || ''
    };
  }
}

const treffer = beste !== null && beste.score >= SCHWELLWERT;

// Genau ein Item zurueckgeben: die Anfrage, ergaenzt um das Suchergebnis.
return [{
  json: {
    ...anfrage,
    treffer: treffer,
    score: beste ? beste.score : 0,
    kandidaten: kandidaten.length,
    getroffene_stichworte: beste ? beste.getroffen : [],
    artikel_kennung:   treffer ? beste.kennung    : '',
    artikel_titel:     treffer ? beste.titel      : '',
    artikel_pruefdatum: treffer ? beste.pruefdatum : '',
    artikel_loesung:   treffer ? beste.loesung    : ''
  }
}];

/*
  Suchtext bilden
  ---------------
  Bereitet die Anfrage fuer den Abgleich mit den Notion-Stichworten vor.

  Zwei Ergebnisse:
  suchtext    - der gesamte Anfragetext, kleingeschrieben und ohne Umlaute
  suchwoerter - die bedeutungstragenden Einzelwoerter daraus
*/

// Woerter, die in fast jeder Supportanfrage vorkommen und deshalb nichts
// ueber das Thema aussagen. Ohne diese Liste wuerde jeder Artikel Punkte
// sammeln und die Bewertung waere wertlos.
const STOPPWOERTER = [
  'ich', 'und', 'oder', 'der', 'die', 'das', 'ein', 'eine', 'einen', 'einem',
  'einer', 'den', 'dem', 'des', 'ist', 'sind', 'war', 'habe', 'hat', 'haben',
  'kann', 'koennen', 'nicht', 'mehr', 'mein', 'meine', 'meinen', 'sich', 'bei',
  'mit', 'von', 'vom', 'fuer', 'auf', 'aus', 'ueber', 'wie', 'was', 'wann',
  'warum', 'man', 'wir', 'ihr', 'bin', 'wird', 'werden', 'noch', 'schon',
  'immer', 'jetzt', 'bitte', 'danke', 'hallo', 'guten', 'morgen', 'abend',
  'hilfe', 'problem', 'frage', 'anfrage', 'funktioniert', 'geht', 'dass',
  'auch', 'nur', 'zum', 'zur', 'als', 'selbst', 'wieder', 'dreimal'
];

/*
  Umlaute werden vereinheitlicht, weil Anfragende sie mal so und mal so
  schreiben. Wichtig: derselbe Schritt wird im naechsten Node auch auf die
  Notion-Stichworte angewendet. Nur wenn beide Seiten gleich behandelt
  werden, findet "zuruecksetzen" auch "zurücksetzen".
*/
function normalisieren(s) {
  return (s || '')
    .toLowerCase()
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss');
}

// Alle Freitextfelder zusammenfassen. Der Geraetename ist bewusst dabei,
// weil dort oft der Geraetetyp steckt, etwa "Etikettendrucker".
const suchtext = normalisieren(
  $json.kurzbeschreibung + ' ' + $json.text + ' ' + $json.geraet
);

/*
  Einzelwoerter herausloesen. Alles, was kein Buchstabe und keine Ziffer ist,
  gilt als Trenner. Woerter unter vier Zeichen fliegen raus, weil sie zu
  unspezifisch sind. Set entfernt Dubletten.
*/
const suchwoerter = [...new Set(
  suchtext
    .split(/[^a-z0-9]+/)
    .filter(wort => wort.length >= 4)
    .filter(wort => !STOPPWOERTER.includes(wort))
)];

return {
  json: {
    ...$json,
    suchtext: suchtext,
    suchwoerter: suchwoerter
  }
};

/*
  Entwurf pruefen
  ---------------
  Fuehrt Anfrage und Entwurf wieder zusammen und prueft, ob ueberhaupt ein
  brauchbarer Entwurf entstanden ist.

  Der Chain-Node gibt nur das Feld text zurueck und verdraengt damit alle
  Angaben der Anfrage. Die holen wir uns vom Node "Treffer bewerten" zurueck.
*/

const anfrage = $('Treffer bewerten').first().json;

const roh = ($json.text || '').trim();

/*
  Das Modell soll KEIN_ENTWURF sagen, wenn der Artikel das Problem nicht
  abdeckt. Das ist der zweite Filter nach dem Punktwert: Der erste prueft,
  ob ein Artikel inhaltlich nahe genug ist, der zweite, ob sich daraus
  ueberhaupt eine Antwort formulieren laesst.
*/
const brauchbar = roh.length > 0 && !roh.toUpperCase().includes('KEIN_ENTWURF');

return [{
  json: {
    ...anfrage,
    entwurf: brauchbar ? roh : '',
    entwurf_ok: brauchbar,
    entwurf_grund: brauchbar ? '' : 'Das Modell konnte aus dem Artikel keine Antwort ableiten'
  }
}];

