/*
  Freigabe auswerten
  ------------------
  Fuehrt Anfrage und Freigabeentscheidung zusammen und bestimmt, welcher
  Text tatsaechlich versendet wird.
*/

const anfrage = $('Entwurf pruefen').first().json;
const antwort = $json.data || {};

// Faellt die Antwort aus, etwa bei Zeitablauf, gilt das als Ablehnung.
// Stillschweigende Freigabe darf es nicht geben.
const entscheidung = (antwort.Entscheidung || 'ablehnen').trim();

// Feldname mit Leerzeichen, deshalb eckige Klammern.
const geaendert = (antwort['Geaenderte Fassung'] || '').trim();
const grund     = (antwort.Grund || '').trim();

const freigegeben = entscheidung === 'freigeben'
                 || entscheidung === 'geaendert freigeben';

/*
  Bei einer geaenderten Fassung gilt der Text der pruefenden Person.
  Bleibt das Feld leer, obwohl "geaendert freigeben" gewaehlt wurde, faellt
  der Workflow auf den urspruenglichen Entwurf zurueck, statt eine leere
  Mail zu verschicken.
*/
const versandtext = (entscheidung === 'geaendert freigeben' && geaendert.length > 0)
  ? geaendert
  : anfrage.entwurf;

return [{
  json: {
    ...anfrage,
    freigabe: entscheidung,
    freigabe_grund: grund,
    freigabe_zeit: antwort.respondedAt || '',
    freigegeben: freigegeben,
    versandtext: freigegeben ? versandtext : ''
  }
}];

/*
  Protokolleintrag erzeugen
  -------------------------
  Erzeugt den Datensatz, der den Vorgang nachvollziehbar macht, ohne eine
  Leistungsauswertung zu ermoeglichen.

  Bewusst nicht enthalten: der Inhalt der Anfrage, der Antworttext und der
  Klarname der freigebenden Person.
*/

const d = $('Freigabe auswerten').first().json;

/*
  Einfache Einwegfunktion fuer die pseudonyme Freigabekennung.
  Fuer den Prototyp ausreichend, um das Prinzip zu zeigen. Im Betrieb waere
  hier ein HMAC mit einem Projektschluessel zu verwenden, der getrennt
  verwahrt wird.
*/
function kennung(text) {
  let h = 0;
  const roh = 'pilot-2026-' + (text || '');
  for (let i = 0; i < roh.length; i++) {
    h = (h * 31 + roh.charCodeAt(i)) >>> 0;
  }
  return 'FR-' + h.toString(16).toUpperCase().padStart(8, '0');
}

// Dauer von der Anfrage bis zur Freigabe, in Minuten.
let dauer = null;
if (d.eingang && d.freigabe_zeit) {
  dauer = Math.round(
    (new Date(d.freigabe_zeit) - new Date(d.eingang)) / 60000
  );
}

return [{
  json: {
    vorgang: d.vorgang,
    zeitpunkt: d.freigabe_zeit,
    quelle: d.quelle,
    kategorie: d.kategorie,
    standort: d.standort,
    pfad: 'Antwort versendet',
    artikel_kennung: d.artikel_kennung,
    artikel_pruefdatum: d.artikel_pruefdatum,
    score: d.score,
    kandidaten: d.kandidaten,
    entscheidung: d.freigabe,
    dauer_minuten: dauer,
    freigabe_kennung: kennung('freigabe-postfach'),
    ungeprueft_versendet: false
  }
}];

/*
  Weiterleitung aufbereiten
  -------------------------
  Sammelpunkt fuer alle Wege, die ohne versendbare Antwort enden.
  Vier Zulaeufe: kein Treffer, kein Entwurf, Vorschlag abgelehnt und
  Wissensdatenbank nicht erreichbar.

  Der Grund wird aus dem jeweils eintreffenden Item abgeleitet, damit der
  First Level sieht, warum der Assistent nicht helfen konnte.
*/

// Die Anfrage selbst liegt in jedem der vier Faelle hier vor.
const a = $('Suchtext bilden').first().json;
const e = $json || {};

let grund;
if (e.freigegeben === false) {
  grund = 'Der Antwortvorschlag wurde bei der Freigabe abgelehnt';
} else if (e.entwurf_ok === false) {
  grund = 'Aus dem gefundenen Wissenseintrag liess sich keine Antwort ableiten';
} else if (e.treffer === false) {
  grund = (e.kandidaten === 0)
    ? 'In dieser Kategorie gibt es keinen freigegebenen Wissenseintrag'
    : 'Es wurde kein ausreichend passender Wissenseintrag gefunden';
} else {
  // Uebrig bleibt der Fehlerzweig des Notion-Nodes.
  grund = 'Die Wissensdatenbank war nicht erreichbar';
}

// Zusatzangaben, soweit sie im jeweiligen Fall ueberhaupt existieren.
const details = [];
if (e.kandidaten !== undefined) {
  details.push('Geprueft: ' + e.kandidaten + ' freigegebene Artikel dieser Kategorie');
}
if (e.artikel_kennung) {
  details.push('Bester Treffer: ' + e.artikel_kennung + ' mit ' + e.score + ' Punkten');
}
if (e.freigabe_grund) {
  details.push('Hinweis der pruefenden Person: ' + e.freigabe_grund);
}

return [{
  json: {
    ...a,
    weiterleitung_grund: grund,
    weiterleitung_details: details.join('\n'),
    pfad: 'Weiterleitung First Level'
  }
}];

