/*
  Bearbeitungsschritte zusammenstellen
  ------------------------------------
  Baut die Historie des Vorgangs, damit der Second Level nicht bei null
  anfaengt. Genau das verlangt die Fallakte bei der Eskalation.
*/

const a = $('Weiterleitung aufbereiten').first().json;
const r = $json.data || {};

const schritte = [];
schritte.push('1. Eingang ueber ' + a.quelle + ', eingegangen ' + a.eingang);
schritte.push('2. Eingangspruefung: ' + a.pruefung);
schritte.push('3. Wissenssuche in der Kategorie ' + a.kategorie);
schritte.push('4. Ergebnis: ' + a.weiterleitung_grund);
if (a.weiterleitung_details) {
  schritte.push('   ' + a.weiterleitung_details.replace(/\n/g, '\n   '));
}
schritte.push('5. Weiterleitung an den First Level');
schritte.push('6. First Level: nicht geloest');
if (r['Was wurde versucht']) {
  schritte.push('   Versucht: ' + r['Was wurde versucht']);
}

return [{
  json: {
    ...a,
    bearbeitungsschritte: schritte.join('\n'),
    first_level_versucht: r['Was wurde versucht'] || '',
    eskalation_zeit: r.respondedAt || '',
    pfad: 'Eskalation Second Level'
  }
}];

