/*
  Angaben ergaenzen
  -----------------
  Fuehrt die urspruengliche Anfrage mit den nachgereichten Angaben zusammen
  und schickt sie zurueck in den normalen Ablauf.

  Bereits vorhandene Werte bleiben erhalten, es wird nur gefuellt, was leer war.
*/

const a = $('Eingangsprüfung').first().json;
const r = $json.data || {};

const geraet   = (r.Geraetename || '').trim() || a.geraet;
const standort = (r.Standort   || '').trim() || a.standort;

return [{
  json: {
    ...a,
    geraet: geraet,
    standort: standort,
    pruefung: 'ok',
    pruefgrund: 'Angaben nachgefordert und ergaenzt',
    nachgefordert: true
  }
}];
